-- L3 isolated synthetic authority/lifecycle fixtures. All identities, grants and evidence roll back.
begin;
select set_config('request.jwt.claim.sub',(select auth_user_id::text from public.employees where id='9f44daf9-9f87-4129-bc71-55c082cf8782'),true);
do $$declare o uuid:=gen_random_uuid();b uuid:=gen_random_uuid();foreign_brand uuid:=gen_random_uuid();u uuid:=gen_random_uuid();editor_u uuid:=gen_random_uuid();e uuid:=gen_random_uuid();editor_e uuid:=gen_random_uuid();r uuid:=gen_random_uuid();editor_r uuid:=gen_random_uuid();t jsonb;result jsonb;request uuid;prior integer;begin
 insert into auth.users(id,email) values(u,'qa-planner-review-'||u||'@example.invalid'),(editor_u,'qa-planner-edit-'||editor_u||'@example.invalid');
 insert into public.roles(id,name,outlet_access_type) values(r,'Disposable Planner Reviewer '||r,'none'),(editor_r,'Disposable Planner Editor '||editor_r,'none');
 insert into public.role_permissions(role_id,permission_id) select r,id from public.permissions where code in ('marketing_workspace.access','marketing_planner.view','marketing_planner.create','marketing_planner.edit','marketing_planner.approve','marketing_planner.delete');
 insert into public.role_permissions(role_id,permission_id) select editor_r,id from public.permissions where code in ('marketing_workspace.access','marketing_planner.view','marketing_planner.edit');
 insert into public.employees(id,full_name,role_id,auth_user_id,enable_system_login,access_state) values(e,'Disposable Planner Reviewer',r,u,true,'active'),(editor_e,'Disposable Planner Editor',editor_r,editor_u,true,'active');
 insert into public.organizations(id,name) values(o,'Disposable Planner Revision Contract');
 insert into public.brands(id,organization_id,name) values(b,o,'Disposable Planner Revision Brand'),(foreign_brand,o,'Disposable Foreign Brand');
 insert into public.organization_memberships values(o,e),(o,editor_e);
 insert into public.platform_member_brands values(o,e,b),(o,editor_e,b);
 perform set_config('request.jwt.claim.sub',u::text,true);
 t:=public.marketing_planner_command(gen_random_uuid(),o,b,'create',null,0,'{"month":"2026-10-01","title":"Disposable review/block task","content_type":"post","due_date":"2026-10-14"}');
 t:=public.marketing_planner_command(gen_random_uuid(),o,b,'block',(t->>'id')::uuid,(t->>'revision')::int,'{"blocked":true}');
 assert t->>'status'='planned' and (t->>'blocked')::boolean and t->>'blocker_reason'='' and t->>'blocker_owner' is null,'Optional blocker must retain Planned';
 t:=public.marketing_planner_command(gen_random_uuid(),o,b,'block',(t->>'id')::uuid,(t->>'revision')::int,jsonb_build_object('blocked',true,'blocker_reason','Awaiting reference','blocker_owner',editor_e));
 assert t->>'blocker_reason'='Awaiting reference','Blocker details not retained';
 t:=public.marketing_planner_command(gen_random_uuid(),o,b,'block',(t->>'id')::uuid,(t->>'revision')::int,'{"blocked":false}');
 assert t->>'blocker_reason'='' and t->>'blocker_owner' is null,'Unblock must clear active details';
 t:=public.marketing_planner_command(gen_random_uuid(),o,b,'transition',(t->>'id')::uuid,(t->>'revision')::int,'{"status":"in_progress"}');
 t:=public.marketing_planner_command(gen_random_uuid(),o,b,'transition',(t->>'id')::uuid,(t->>'revision')::int,'{"status":"in_review"}');
 t:=public.marketing_planner_command(gen_random_uuid(),o,b,'block',(t->>'id')::uuid,(t->>'revision')::int,'{"blocked":true}');
 assert t->>'status'='in_review','Blocking cannot reopen review';
 begin perform public.marketing_planner_command(gen_random_uuid(),o,b,'approve',(t->>'id')::uuid,(t->>'revision')::int,'{}');raise exception 'Blocked approval accepted';exception when raise_exception then if sqlerrm='Blocked approval accepted' then raise;end if;end;
 t:=public.marketing_planner_command(gen_random_uuid(),o,b,'block',(t->>'id')::uuid,(t->>'revision')::int,'{"blocked":false}');
 perform set_config('request.jwt.claim.sub',editor_u::text,true);
 begin perform public.marketing_planner_command(gen_random_uuid(),o,b,'request_revision',(t->>'id')::uuid,(t->>'revision')::int,'{}');raise exception 'Editor requested revision';exception when insufficient_privilege then null;end;
 begin perform public.marketing_planner_command(gen_random_uuid(),o,foreign_brand,'block',(t->>'id')::uuid,(t->>'revision')::int,'{"blocked":true}');raise exception 'Foreign Brand accepted';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claim.sub',u::text,true);
 request:=gen_random_uuid();prior:=(t->>'revision')::int;
 t:=public.marketing_planner_command(request,o,b,'request_revision',(t->>'id')::uuid,prior,'{}');
 result:=public.marketing_planner_command(request,o,b,'request_revision',(t->>'id')::uuid,prior,'{}');
 assert t=result and t->>'status'='revision_needed' and t->>'review_feedback'='','Blank feedback transition/retry failed';
 t:=public.marketing_planner_command(gen_random_uuid(),o,b,'transition',(t->>'id')::uuid,(t->>'revision')::int,'{"status":"in_review"}');
 t:=public.marketing_planner_command(gen_random_uuid(),o,b,'request_revision',(t->>'id')::uuid,(t->>'revision')::int,'{"feedback":"Revise the approved composition"}');
 assert t->>'review_feedback'='Revise the approved composition','Supplied feedback missing';
 assert exists(select 1 from marketing_private.creative_task_revisions where task_id=(t->>'id')::uuid and action='request_revision' and snapshot->>'review_feedback'=''),'Blank feedback history missing';
 t:=public.marketing_planner_command(gen_random_uuid(),o,b,'transition',(t->>'id')::uuid,(t->>'revision')::int,'{"status":"in_review"}');
 t:=public.marketing_planner_command(gen_random_uuid(),o,b,'approve',(t->>'id')::uuid,(t->>'revision')::int,'{}');
 t:=public.marketing_planner_command(gen_random_uuid(),o,b,'block',(t->>'id')::uuid,(t->>'revision')::int,'{"blocked":true}');
 assert t->>'status'='completed' and t->>'approved_revision'=t->>'revision','Administrative blocking lost existing approval';
 begin perform public.marketing_planner_command(gen_random_uuid(),o,b,'handoff',(t->>'id')::uuid,(t->>'revision')::int,'{}');raise exception 'Blocked handoff accepted';exception when raise_exception then if sqlerrm='Blocked handoff accepted' then raise;end if;end;
 begin perform public.marketing_planner_command(gen_random_uuid(),o,b,'block',(t->>'id')::uuid,(t->>'revision')::int,'{"blocked":false,"title":"Unexpected creative edit"}');raise exception 'Blocking changed creative data';exception when raise_exception then if sqlerrm='Blocking changed creative data' then raise;end if;end;
 begin perform public.marketing_planner_command(gen_random_uuid(),o,b,'block',(t->>'id')::uuid,1,'{"blocked":false}');raise exception 'Stale blocker accepted';exception when serialization_failure then null;end;
 t:=public.marketing_planner_command(gen_random_uuid(),o,b,'block',(t->>'id')::uuid,(t->>'revision')::int,'{"blocked":false}');
 t:=public.marketing_planner_command(gen_random_uuid(),o,b,'delete',(t->>'id')::uuid,(t->>'revision')::int,'{}');
 assert t->>'deleted_at' is not null and exists(select 1 from marketing_private.creative_task_revisions where task_id=(t->>'id')::uuid and action='block' and snapshot->>'blocker_reason'='Awaiting reference'),'Removal erased blocker history';
 assert not has_function_privilege('anon','public.marketing_planner_command(uuid,uuid,uuid,text,uuid,integer,jsonb)','execute'),'Anonymous mutation grant';
end;$$;
rollback;
